def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Check if opponent ever retaliated against our defection
    retaliates = False
    for i in range(n-1):
        if history[i][0] == 'D' and history[i+1][1] == 'D':
            retaliates = True
            break

    # Count opponent cooperations
    opp_coops = sum(1 for _, o in history if o == 'C')
    coop_rate = opp_coops / n

    last_me, last_opp = history[-1]

    # Endgame: defect on the last round, and if safe, on the second to last
    if n >= 99:
        return 'D'
    if n == 98:
        if not retaliates:
            return 'D'
        else:
            return 'C'

    # If we defected last round and opponent cooperated, continue exploiting if safe
    if last_me == 'D' and last_opp == 'C':
        if not retaliates:
            return 'D'
        else:
            return 'C'

    # If opponent cooperated last round
    if last_opp == 'C':
        # Probe if we have never defected and opponent seems very cooperative
        if not retaliates:
            ever_defected = False
            for m, o in history:
                if m == 'D':
                    ever_defected = True
                    break
            if not ever_defected and n >= 20 and coop_rate > 0.95 and n < 80:
                return 'D'
        return 'C'

    # Opponent defected last round
    # Count consecutive defections
    cons = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            cons += 1
        else:
            break

    if cons == 1:
        if coop_rate > 0.9:
            return 'C'
        else:
            return 'D'
    if cons == 2:
        return 'D'
    if cons >= 3:
        if coop_rate > 0.7:
            return 'C'
        else:
            return 'D'
    return 'D'
